                                    <Form.Label>
                                        <b>
                                            CVC Number
                                        </b>
                                    </Form.Label>


                                    <Form.Control
                                        type="text"
                                        inputMode="numeric"
                                        pattern="[0-9]{3}"
                                        value={cvc}
                                        onChange={(e) => {

                                            const value =
                                                e.target.value
                                                    .replace(
                                                        /\D/g,
                                                        ""
                                                    )
                                                    .slice(
                                                        0,
                                                        3
                                                    )

                                            setCvc(value)
                                        }}
                                        placeholder="123"
                                        maxLength="3"
                                        required
                                    />

                                </Form.Group>

                            </Col>

                        </Row>


                        {/* =====================================
                            SAVE CARD CHECKBOX
                        ===================================== */}

                        {!differentCard && (

                            <Form.Group className="mb-3">

                                <Form.Check
                                    type="checkbox"
                                    id="saveCard"
                                    label="Save my card for future payments"
                                    checked={saveCard}
                                    onChange={(e) =>
                                        setSaveCard(
                                            e.target.checked
                                        )
                                    }
                                />

                            </Form.Group>

                        )}


                        {/* =====================================
                            SUBMIT
                        ===================================== */}

                        <Button
                            className="btn-sm"
                            variant="primary"
                            type="submit"
                        >

                            Submit

                        </Button>

                    </Form>
                )}

            </div>


            {/* =====================================
                SAVED CARDS
            ===================================== */}

            <div className="my-4 card px-4 py-4">

                <h5>
                    Saved Card
                </h5>


                {stripeCards &&
                stripeCards.length > 0 ? (

                    stripeCards.map(
                        (cardData) => (

                            <div
                                key={cardData.id}
                                className="mb-3"
                            >

                                <Card
                                    className="p-3"
                                    style={{
                                        border:
                                            "1px solid #C6ACE7"
                                    }}
                                >

                                    {/* CARD NUMBER */}

                                    <p>

                                        <b>
                                            Card Number:
                                        </b>{" "}

                                        XXXX XXXX XXXX{" "}

                                        {
                                            cardData.card_number
                                                ? cardData.card_number.slice(-4)
                                                : "----"
                                        }

                                    </p>


                                    {/* CARD ACTIONS */}

                                    <div>

                                        {showCardDetails(
                                            cardData
                                        )}


                                        <button
                                            type="button"
                                            onClick={() => {

                                                setCardDetails(
                                                    true
                                                )

                                                setCardDetailsId(
                                                    cardData.id
                                                )
                                            }}
                                            className="btn btn-sm btn-outline-primary"
                                        >

                                            Show Card Details

                                        </button>


                                        <button
                                            type="button"
                                            onClick={() =>
                                                payWithSavedCard(
                                                    cardData
                                                )
                                            }
                                            className="ml-2 btn btn-sm btn-outline-primary"
                                        >

                                            Pay with this Card

                                        </button>

                                    </div>

                                </Card>


                                {/* EDIT CARD */}

                                <span
                                    onClick={() =>
                                        history.push(
                                            "/stripe-card-details/"
                                        )
                                    }
                                    style={{
                                        cursor: "pointer"
                                    }}
                                >

                                    <i
                                        title="Edit card"
                                        className="fas fa-edit fa-lg edit-button-css mr-2"
                                    ></i>

                                </span>

                            </div>

                        )
                    )

                ) : (

                    <p className="text-muted mb-0">
                        No saved card.
                    </p>

                )}

            </div>

        </div>
    )
}


export default CreateCardComponent
